const prices = [4500, 1200, 800, 2800];

function calculateTotal(priceList) {
  let total = 0;
  for (const price of priceList) {
    total = total + price;
  }
  return total;
}

const result = calculateTotal(prices);
console.log('Total: ₦' + result);

