questions.solution:
const orders = [
  { customer: 'Amara', amount: 4500, status: 'delivered' },
  { customer: 'Bayo',  amount: 1200, status: 'delivered' },
  { customer: 'Chidi', amount: 8000, status: 'cancelled' },
  { customer: 'Dami',  amount: 600,  status: 'delivered' }
];

function summariseOrders(orderList) {
  let revenue = 0;
  for (const order of orderList) {
    if (order.status === 'delivered') {
      revenue = revenue + order.amount;
    }
  }
  return { count: orderList.length, revenue: revenue };
}

const summary = summariseOrders(orders);
console.log('Count:', summary.count);
console.log('Revenue: ₦' + summary.revenue);

